import {loadBuilderData,newBuilderDraft,buildCharacter,builderProblems,availableOrigins,builderId,abilities,title,plain,describeEquipment} from './character-builder-rules.mjs';
import {escape,signed} from './format.mjs';
import {formatEntries} from './rules-library.mjs';
const draftKey='wayfarer-character-builder-v1',steps=['Identity','Origins & class','Ability scores','Training & features','Equipment','Spells','Review'];
function normalizeDraft(saved){
 if(!saved?.baseScores)return newBuilderDraft();
 // Legacy drafts lacked visit tracking; only count steps the player has already reached.
 if(!Array.isArray(saved.visitedSteps))saved.visitedSteps=[...Array(Math.max(0,Number(saved.step)||0)+1).keys()];
 return saved;
}
function markStepVisited(step){
 const n=Number(step);
 if(!Array.isArray(draft.visitedSteps))draft.visitedSteps=[];
 if(!draft.visitedSteps.includes(n))draft.visitedSteps.push(n);
}
let draft;try{draft=normalizeDraft(JSON.parse(localStorage.getItem(draftKey)));}catch{draft=newBuilderDraft();}
let db,root,onCreate,onClose,error='',saving=false;
const searches=new Map(),scrolls=new Map(),activeSpellTabs=new Map(),activeSpellFilters=new Map();
const schoolNames={A:'Abjuration',C:'Conjuration',D:'Divination',E:'Enchantment',V:'Evocation',I:'Illusion',N:'Necromancy',T:'Transmutation'};
const schoolOf=s=>schoolNames[s]??(typeof s==='string'&&s.length>1?s:'Magic');
const levelLabel=lvl=>lvl===0?'Cantrips':lvl===1?'1st Level':lvl===2?'2nd Level':lvl===3?'3rd Level':`${lvl}th Level`;
const spellTimeDisplay=time=>(!time||!time.length)?'1 action':time.map(t=>`${t.number?t.number+' ':''}${t.unit==='bonus'?'bonus action':t.unit}`).join(' / ');
const store=()=>{try{localStorage.setItem(draftKey,JSON.stringify(draft));}catch{error='This browser could not save the draft. Keep this page open until you finish.';}};
const option=(id,name,selected=false,disabled=false)=>`<option value="${escape(id)}" ${selected?'selected':''} ${disabled?'disabled':''}>${escape(name)}</option>`;
const select=(label,key,options)=>`<label class="builder-field">${escape(label)}<select data-build="${escape(key)}" aria-label="${escape(label)}">${options}</select></label>`;
function increaseLabel(record){const weights=record.choose?.weighted?.weights;if(weights)return weights.every(n=>n===1)?'+1 to '+weights.length+' different abilities':weights.map(n=>'+'+n).join(' and ')+' to different abilities';if(record.choose)return '+'+(record.choose.amount??1)+' to '+(record.choose.count??1)+' chosen abilities';return Object.entries(record).filter(([key])=>abilities.includes(key)).map(([key,n])=>key.toUpperCase()+' +'+n).join(', ')||'Ability increase';}
function spellChoiceHTML(c){
  const selectedCount=c.selected.length,bad=c.selected.some(id=>c.options.some(o=>o.id===id&&o.disabled));
  const distinctLevels=[...new Set(c.options.map(o=>o.level??0))].sort((a,b)=>a-b);
  const currentTab=activeSpellTabs.has(c.id)&&distinctLevels.includes(activeSpellTabs.get(c.id))?activeSpellTabs.get(c.id):(distinctLevels[0]??0);
  if(!activeSpellTabs.has(c.id))activeSpellTabs.set(c.id,currentTab);
  const activeFilters=activeSpellFilters.get(c.id)??new Set();
  const presentSchools=[...new Set(c.options.map(o=>schoolOf(o.school)).filter(Boolean))].sort();
  const hasConcentration=c.options.some(o=>o.concentration),hasRitual=c.options.some(o=>o.ritual);
  const hasBonus=c.options.some(o=>o.castingCategory==='bonus'),hasAction=c.options.some(o=>o.castingCategory==='action'),hasReaction=c.options.some(o=>o.castingCategory==='reaction');
  const spellsInTab=c.options.filter(o=>(o.level??0)===currentTab);
  const visibleSpells=spellsInTab.filter(o=>{
    for(const tag of activeFilters){
      if(tag.startsWith('school:')){if(schoolOf(o.school)!==tag.slice(7))return false;}
      else if(tag==='prop:concentration'){if(!o.concentration)return false;}
      else if(tag==='prop:ritual'){if(!o.ritual)return false;}
      else if(tag.startsWith('time:')){if(o.castingCategory!==tag.slice(5))return false;}
    }
    return true;
  });
  return `<section class="builder-choice builder-spell-choice" data-choice-id="${escape(c.id)}">
    <header class="builder-spell-choice-header">
      <div>
        <h3>${escape(c.label)}</h3>
        <p class="builder-spell-choice-desc">${c.instruction?escape(c.instruction):(c.kind==='prepared'?'Prepare your daily spells grouped by spell level.':c.kind==='spellbook'?'Record starting spells in your spellbook by level.':'Choose spells for your adventurer.')}</p>
      </div>
      <span class="builder-count ${bad?'needs-choice':''}">${selectedCount} / ${c.count}${c.optional&&c.kind!=='prepared'?' optional':''}</span>
    </header>
    ${distinctLevels.length>1?`
      <div class="builder-spell-tabs" role="tablist" aria-label="Spell level tabs">
        ${distinctLevels.map(lvl=>{
          const inLvl=c.options.filter(o=>(o.level??0)===lvl),prepInLvl=inLvl.filter(o=>c.selected.includes(o.id)).length,isSelected=lvl===currentTab;
          return `<button type="button" role="tab" class="builder-spell-tab" data-spell-choice-id="${escape(c.id)}" data-spell-tab="${lvl}" aria-selected="${isSelected?'true':'false'}" id="tab-${escape(c.id)}-${lvl}">
            <span>${levelLabel(lvl)}</span>
            <span class="builder-tab-badge ${prepInLvl>0?'active':''}">${prepInLvl>0?prepInLvl+' prep':'('+inLvl.length+')'}</span>
          </button>`;
        }).join('')}
      </div>`:''}
    <div class="builder-spell-toolbar">
      <div class="builder-field builder-filter">
        <input type="search" placeholder="Search spells by name or school..." data-choice-search aria-label="Search spells">
      </div>
      <div class="builder-spell-tags-bar" role="group" aria-label="Filter tags">
        <span class="builder-filter-label">Filter:</span>
        ${hasConcentration?`<button type="button" class="builder-filter-tag ${activeFilters.has('prop:concentration')?'active':''}" data-spell-choice-id="${escape(c.id)}" data-spell-tag="prop:concentration" aria-pressed="${activeFilters.has('prop:concentration')}">Concentration</button>`:''}
        ${hasRitual?`<button type="button" class="builder-filter-tag ${activeFilters.has('prop:ritual')?'active':''}" data-spell-choice-id="${escape(c.id)}" data-spell-tag="prop:ritual" aria-pressed="${activeFilters.has('prop:ritual')}">Ritual</button>`:''}
        ${hasBonus?`<button type="button" class="builder-filter-tag ${activeFilters.has('time:bonus')?'active':''}" data-spell-choice-id="${escape(c.id)}" data-spell-tag="time:bonus" aria-pressed="${activeFilters.has('time:bonus')}">Bonus Action</button>`:''}
        ${hasAction?`<button type="button" class="builder-filter-tag ${activeFilters.has('time:action')?'active':''}" data-spell-choice-id="${escape(c.id)}" data-spell-tag="time:action" aria-pressed="${activeFilters.has('time:action')}">Action</button>`:''}
        ${hasReaction?`<button type="button" class="builder-filter-tag ${activeFilters.has('time:reaction')?'active':''}" data-spell-choice-id="${escape(c.id)}" data-spell-tag="time:reaction" aria-pressed="${activeFilters.has('time:reaction')}">Reaction</button>`:''}
        ${presentSchools.map(sch=>`<button type="button" class="builder-filter-tag ${activeFilters.has('school:'+sch)?'active':''}" data-spell-choice-id="${escape(c.id)}" data-spell-tag="school:${escape(sch)}" aria-pressed="${activeFilters.has('school:'+sch)}">${escape(sch)}</button>`).join('')}
        ${activeFilters.size>0?`<button type="button" class="builder-filter-clear" data-spell-clear-filters="${escape(c.id)}">Reset filters</button>`:''}
      </div>
    </div>
    <div class="builder-options builder-spell-cards" role="tabpanel" id="panel-${escape(c.id)}-${currentTab}" aria-labelledby="tab-${escape(c.id)}-${currentTab}">
      ${visibleSpells.length?visibleSpells.map(o=>{
        const isChecked=c.selected.includes(o.id),isDisabled=o.disabled&&!isChecked,sch=schoolOf(o.school),timeStr=spellTimeDisplay(o.time);
        return `<div class="builder-option builder-spell-card ${isChecked?'is-prepared':''}" data-search-name="${escape((o.name+' '+(o.source??'')+' '+sch).toLowerCase())}">
          <label class="builder-spell-card-header">
            <input type="checkbox" data-build-choice="${escape(c.id)}" value="${escape(o.id)}" ${isChecked?'checked':''} ${isDisabled?'disabled':''}>
            <div class="builder-spell-title-col">
              <div class="builder-spell-name-row">
                <strong class="builder-spell-name">${escape(o.name)}</strong>
                ${isChecked?'<span class="builder-prepared-badge">Prepared ✓</span>':''}
              </div>
              <div class="builder-spell-tags">
                <span class="builder-spell-meta-badge school">${escape(sch)}</span>
                <span class="builder-spell-meta-badge time">${escape(timeStr)}</span>
                ${o.range?`<span class="builder-spell-meta-badge range">${escape(o.range)}</span>`:''}
                ${o.concentration?'<span class="builder-spell-meta-badge concentration">Conc.</span>':''}
                ${o.ritual?'<span class="builder-spell-meta-badge ritual">Ritual</span>':''}
                ${o.source?`<span class="builder-spell-meta-badge source">${escape(o.source)}</span>`:''}
              </div>
            </div>
          </label>
          ${o.requires?`<small class="builder-requirement">${escape(o.requires)}</small>`:''}
          ${o.entries?`<details class="builder-spell-details" data-choice-rules="${escape(c.id)}" data-option-rules="${escape(o.id)}" data-loaded="true">
            <summary>Read details</summary>
            <div class="builder-spell-rules-body">${formatEntries(o.entries)}${o.entriesHigherLevel?formatEntries(o.entriesHigherLevel):''}</div>
          </details>`:''}
        </div>`;
      }).join(''):`<div class="builder-spells-empty"><p>No spells match the active filters for this level.</p>${activeFilters.size>0?`<button type="button" class="button outline small" data-spell-clear-filters="${escape(c.id)}">Reset filters</button>`:''}</div>`}
    </div>
  </section>`;
}
function choicesHTML(choices){return choices.map(c=>{
  if(['prepared','spells','spellbook','granted-spells'].includes(c.kind)&&c.options.some(o=>o.level!=null))return spellChoiceHTML(c);
  const selected=c.selected.length,bad=c.selected.some(id=>c.options.some(o=>o.id===id&&o.disabled));return `<section class="builder-choice" data-choice-id="${escape(c.id)}"><header><h3>${escape(c.label)}</h3><span class="builder-count ${bad?'needs-choice':''}">${selected} / ${c.count}${c.optional&&c.kind!=='prepared'?' optional':''}</span></header>${c.instruction?`<p>${escape(c.instruction)}</p>`:''}
 ${c.kind==='record'?`<label class="builder-field">Your choice<input data-note="${escape(c.id)}" maxlength="300" value="${escape(c.note)}"></label>`:`${c.options.length>16?'<label class="builder-field builder-filter">Find an option<input type="search" placeholder="Search by name or source" data-choice-search></label>':''}<div class="builder-options">${c.options.map(o=>`<div class="builder-option" data-search-name="${escape((o.name+' '+(o.source??'')).toLowerCase())}"><label><input type="checkbox" data-build-choice="${escape(c.id)}" value="${escape(o.id)}" ${c.selected.includes(o.id)?'checked':''} ${o.disabled&&!c.selected.includes(o.id)?'disabled':''}><span><strong>${escape(o.name)}</strong>${o.source?`<small>${escape(o.source)}${o.level!=null?' · '+(o.level?'Level '+o.level:'Cantrip'):''}</small>`:''}</span></label>${o.requires?`<small class="builder-requirement">${escape(o.requires)}</small>`:''}${o.entries?`<details data-choice-rules="${escape(c.id)}" data-option-rules="${escape(o.id)}"><summary>Read rules</summary></details>`:''}</div>`).join('')}</div>`}</section>`;}).join('');}
function content(context,problems){const {character,cls,species,background,equipment,abilityInfo}=context;
 switch(draft.step){
 case 0:return `<h2>Who will you play?</h2><p>Create a character from the local 5etools rules, then use the sheet in any adventure room.</p><div class="builder-fields"><label class="builder-field">Character name<input data-build="name" maxlength="80" value="${escape(draft.name)}" placeholder="Your character’s name" autocomplete="off"></label><label class="builder-field">Player name (optional)<input data-build="player" maxlength="60" value="${escape(draft.player)}"></label>${select('Rules edition','edition',[['2014','2014 · classic 5e'],['2024','2024 · revised 5e']].map(([id,label])=>option(id,label,draft.edition===id)).join(''))}${select('Starting level','level',Array.from({length:20},(_,i)=>option(i+1,'Level '+(i+1),draft.level===i+1)).join(''))}</div><p class="builder-hint">Start at level 1 for a new adventurer. Higher levels include their unlocked subclass, feature, and spell choices. This builder creates one class; imported multiclass sheets remain supported.</p>`;
 case 1:{const details=character.rulesDetails.classDetails.classes[0];return `<h2>Choose your origins and class</h2><div class="builder-fields">${select('Class','classId',db.features.classes.filter(c=>c.edition===draft.edition&&!c.source.startsWith('UA')).map(c=>option(builderId(c),c.name+' · '+c.source,draft.classId===builderId(c))).join(''))}${select('Species / lineage','speciesId',availableOrigins(db,'species',draft.edition).map(s=>option(builderId(s),s.name+' · '+s.source,draft.speciesId===builderId(s))).join(''))}${species.subraces?.length?select('Subrace / variant','subraceId',species.subraces.map(s=>option(s.id,s.name+(s.source&&s.source!==species.source?' · '+s.source:''),draft.subraceId===s.id)).join('')):''}${select('Background','backgroundId',availableOrigins(db,'backgrounds',draft.edition).map(s=>option(builderId(s),s.name+' · '+s.source,draft.backgroundId===builderId(s))).join(''))}
 ${species.size?.length>1?select('Character size','size',option('','Choose size',!draft.size)+species.size.map(size=>option(size,({S:'Small',M:'Medium'})[size]??size,draft.size===size)).join('')):''}
 ${draft.level>=details.subclassLevel?select(details.subclassTitle,'subclass',option('','Choose a subclass',!draft.subclass)+details.subclasses.map(s=>option(s.id,s.name+' · '+s.source,draft.subclass===s.id)).join('')):`<p class="builder-hint">${details.subclassTitle} becomes available at level ${details.subclassLevel}.</p>`}</div><div class="builder-source-grid">${[species,background].map(s=>`<details><summary>${escape(s.name)} · ${escape(s.source)}</summary>${formatEntries(s.entries??[])}</details>`).join('')}<details><summary>${escape(cls.name)} features through level ${draft.level}</summary><ul>${character.rulesDetails.classDetails.features.map(f=>`<li>Level ${f.level} · ${escape(f.name)}</li>`).join('')}</ul></details></div>`;}
 case 2:{const cost={8:0,9:1,10:2,11:3,12:4,13:5,14:7,15:9},spent=Object.values(draft.baseScores).reduce((n,s)=>n+(cost[s]??0),0);return `<h2>Assign ability scores</h2>${select('Ability score method','method',[['standard','Standard array · 15, 14, 13, 12, 10, 8'],['point','27-point buy'],['manual','Rolled / manual scores']].map(([id,label])=>option(id,label,draft.method===id)).join(''))}${draft.method==='point'?`<p class="builder-points">${27-spent} / 27 points left · increases are added below</p>`:''}<div class="builder-abilities">${abilities.map(a=>`<label class="builder-ability"><strong>${a.toUpperCase()}</strong>${draft.method==='standard'?`<select aria-label="${a.toUpperCase()} base score" data-score="${a}">${[15,14,13,12,10,8].map(n=>option(n,n,draft.baseScores[a]===n)).join('')}</select>`:`<input type="number" aria-label="${a.toUpperCase()} base score" data-score="${a}" min="${draft.method==='point'?8:3}" max="${draft.method==='point'?15:18}" value="${draft.baseScores[a]}">`}<span>${draft.baseScores[a]} + ${context.scoreBonuses[a]} = <b>${character.abilities.find(x=>x.abbr===a.toUpperCase()).score}</b></span><small>Modifier ${signed(context.mod[a])}</small></label>`).join('')}</div>
 ${abilityInfo.filter(info=>info.groups.length||info.alternatives?.length>1||Object.keys(info.fixed).length).map(info=>`<section class="builder-choice"><h3>${escape(info.source.name)} · ability increases</h3>${info.alternatives?.length>1?select('Increase option','abilityOptions.'+info.id,info.alternatives.map((a,i)=>option(i,increaseLabel(a),info.option===i)).join('')):''}${Object.keys(info.fixed).length?`<p>Automatic: ${Object.entries(info.fixed).map(([a,n])=>a.toUpperCase()+' +'+n).join(', ')}</p>`:''}<div class="builder-fields">${info.groups.map(g=>select(g.label,'allocations.'+g.id,option('','Choose ability',!draft.allocations[g.id])+g.from.map(a=>option(a,a.toUpperCase(),draft.allocations[g.id]===a)).join(''))).join('')}</div></section>`).join('')}`;}
 case 3:{const fixed=character.rulesDetails;return `<h2>Training and class choices</h2><p>Your fixed proficiencies are already included. Choose the remaining skills, tools, languages, feats, and class options.</p><div class="builder-grants"><p><strong>Languages:</strong> ${escape(fixed.languages.join(', ')||'None yet')}</p><p><strong>Skills:</strong> ${escape(fixed.skillTraining.join(', ')||'Choose below')}</p><p><strong>Armor:</strong> ${escape(fixed.armor.join(', ')||'None')}</p><p><strong>Weapons:</strong> ${escape(fixed.weapons.join(', ')||'None')}</p></div>${choicesHTML(context.choices.filter(c=>!['spells','spellbook','prepared','granted-spells','spell-branch','casting-ability'].includes(c.kind)))}`;}
 case 4:return `<h2>Starting equipment</h2><p>Choose the packages offered by your class and background. Starting gold is included when the source grants it.</p>${equipment.groups.map(g=>`<section class="builder-choice"><h3>${escape(g.label)}</h3><div class="builder-packages">${g.options.map(o=>`<label><input type="radio" name="gear-${escape(g.id)}" data-package="${escape(g.id)}" value="${escape(o.id)}" ${g.selected===o.id?'checked':''}><span>${escape(o.entries.map(describeEquipment).join(' + '))}</span></label>`).join('')}</div></section>`).join('')}${equipment.selectors.map(s=>select(s.label,'gearChoices.'+s.id,option('','Choose an item',!draft.gearChoices[s.id])+s.options.map(i=>option(builderId(i),i.name,draft.gearChoices[s.id]===builderId(i))).join(''))).join('')}
 <div class="builder-fields">${select('Worn armor','armor',option('unarmored','No armor',draft.armor==='unarmored')+context.armorItems.map((i,index)=>option(builderId(i),i.name,draft.armor===builderId(i)||!draft.armor&&index===0)).join(''))}${equipment.items.some(i=>i.type?.split('|')[0]==='S')?`<label class="builder-check"><input type="checkbox" data-build="shield" ${draft.shield?'checked':''}> Equip shield (+2 AC)</label>`:''}</div><h3>Your inventory · ${equipment.copper/100} gp</h3><ul class="builder-inventory">${equipment.items.map(i=>`<li>${i.quantity} × ${escape(i.name)}</li>`).join('')}</ul>`;
 case 5:{const choices=context.choices.filter(c=>['spells','spellbook','prepared','granted-spells','spell-branch','casting-ability'].includes(c.kind));return `<h2>Spells and preparation</h2><p>Spell choices are filtered by your class, subclass, edition, and available spell levels. A wizard chooses a spellbook first, then prepares spells from that book.</p>${choices.length?choicesHTML(choices):'<p class="builder-grants">Your current class and origin do not require spell selections at this level.</p>'}${character.spells.length?`<h3>Current spell list</h3><p>${character.spells.map(s=>escape(s.name)+(s.prepared?' ✓':'')).join(' · ')}</p>`:''}`;}
 case 6:return `<h2>Ready for adventure?</h2><p>${escape(draft.name||'Your character')} · level ${draft.level} ${escape(cls.name)} · ${escape(species.name)} · ${escape(background.name)}</p><div class="builder-review-stats"><span><b>${character.hp??character.maxHp}</b> HP</span><span><b>${character.ac??character.rulesDetails.baseAC}</b> AC</span><span><b>${escape(character.speed??'30')}</b> ft</span><span><b>+${character.proficiency}</b> proficiency</span></div><p>HP uses maximum at level 1 and the fixed average for later levels, with Constitution and selected toughness bonuses.</p>${problems.length?`<section class="builder-issues" role="status"><h3>${problems.length} choices to finish</h3>${problems.map(p=>`<button type="button" data-builder-step="${p.step}">${escape(p.message)}</button>`).join('')}</section>`:'<p class="builder-ready">All required choices are complete. Create the sheet, then use Party → Add in an adventure room.</p>'}<h3>Equipment · ${equipment.copper/100} gp</h3><p>${equipment.items.map(i=>(i.quantity>1?i.quantity+' × ':'')+escape(i.name)).join(' · ')||'Starting gold package'}</p><h3>Features</h3><p>${[...new Set(character.rulesDetails.classDetails.features.map(f=>f.name))].map(escape).join(' · ')}</p><h3>Spells</h3><p>${character.spells.map(s=>escape(s.name)).join(' · ')||'None'}</p><h3>Languages</h3><p>${character.rulesDetails.languages.map(escape).join(', ')}</p>`;
 }}
function paint(){if(!root?.isConnected||!db)return;let context;try{context=buildCharacter(draft,db);}catch(failure){root.innerHTML=`<h1>Character builder</h1><p class="builder-error" role="alert">${escape(failure.message)} Your saved draft has been kept.</p><button type="button" class="button outline" data-builder-action="close">Back to character sheets</button><button type="button" class="button outline" data-builder-action="reset">Start a new draft</button>`;return;}
 markStepVisited(draft.step);
 const problems=builderProblems(draft,context),active=document.activeElement,focusChoice=active?.dataset?.buildChoice,focusValue=active?.value,key=active?.getAttribute('data-build')??active?.getAttribute('data-score'),scroll=root.querySelector('.builder-body')?.scrollTop??0;
 for(const c of root.querySelectorAll('[data-choice-id]'))scrolls.set(c.dataset.choiceId,c.querySelector('.builder-options')?.scrollTop??0);
 root.innerHTML=`<header class="page-heading"><div><h1>Character builder</h1><p>Draft saved in this browser · ${escape(db.version)}</p></div><button type="button" class="button outline" data-builder-action="close">Back to character sheets</button></header><div class="character-builder-layout"><nav class="builder-steps" aria-label="Character creation steps">${steps.map((name,i)=>{const seen=(draft.visitedSteps??[]).includes(i),done=seen&&!problems.some(p=>p.step===i);return `<button type="button" data-builder-step="${i}" aria-current="${i===draft.step?'step':'false'}"><small>${i+1}</small>${name}${done?'<span aria-label="Complete">✓</span>':'<span aria-label="Incomplete">○</span>'}</button>`;}).join('')}<button type="button" class="builder-reset" data-builder-action="reset">Start a new draft</button></nav><section class="builder-body panel" aria-label="${steps[draft.step]}">${content(context,problems)}${error?`<p class="builder-error" role="alert">${escape(error)}</p>`:''}<footer class="builder-footer"><button type="button" class="button outline" data-builder-action="back" ${draft.step===0?'disabled':''}>Back</button><span>Step ${draft.step+1} of ${steps.length}</span>${draft.step===6?`<button type="button" class="button primary" data-builder-action="create" ${problems.length||saving?'disabled':''}>${saving?'Saving…':'Create character'}</button>`:'<button type="button" class="button primary" data-builder-action="next">Next</button>'}</footer></section></div>`;
 for(const c of root.querySelectorAll('[data-choice-id]')){const query=searches.get(c.dataset.choiceId)??'',input=c.querySelector('[data-choice-search]');if(input)input.value=query;for(const item of c.querySelectorAll('[data-search-name]'))item.hidden=!item.dataset.searchName.includes(query.toLowerCase());const options=c.querySelector('.builder-options');if(options)options.scrollTop=scrolls.get(c.dataset.choiceId)??0;}
 if(focusChoice){[...root.querySelectorAll('[data-build-choice]')].find(e=>e.dataset.buildChoice===focusChoice&&e.value===focusValue)?.focus({preventScroll:true});}
 if(key){const target=[...root.querySelectorAll('[data-build],[data-score]')].find(e=>(e.getAttribute('data-build')??e.getAttribute('data-score'))===key);target?.focus({preventScroll:true});}if(root.querySelector('.builder-body'))root.querySelector('.builder-body').scrollTop=scroll;
}
function update(event){const input=event.target;if(!root?.contains(input))return;if(input.matches('[data-choice-search]')){const q=input.value.toLowerCase();searches.set(input.closest('[data-choice-id]').dataset.choiceId,input.value);for(const item of input.closest('.builder-choice').querySelectorAll('[data-search-name]'))item.hidden=!item.dataset.searchName.includes(q);return;}
 error='';const key=input.dataset.build;
 if(key){if(key==='name'||key==='player'){draft[key]=input.value;store();return;}const [group,...parts]=key.split('.');if(parts.length)draft[group][parts.join('.')]=input.value;else draft[key]=input.type==='checkbox'?input.checked:key==='level'?Number(input.value):input.value;
 if(['classId','level','edition'].includes(key)){draft.featureChoices={};draft.notes={};draft.subclass='';draft.equipment={};draft.gearChoices={};draft.armor='';draft.allocations=Object.fromEntries(Object.entries(draft.allocations).filter(([k])=>!k.startsWith('asi:')&&!k.startsWith('feat:')));activeSpellTabs.clear();activeSpellFilters.clear();searches.clear();}
 if(key==='edition'){const source=draft.edition==='2024'?'xphb':'phb';draft.classId='fighter|'+source;draft.speciesId='human|'+source;draft.subraceId=draft.edition==='2024'?'':'standard';draft.backgroundId='soldier|'+source;draft.allocations={};draft.abilityOptions={};}
 if(['speciesId','backgroundId'].includes(key)){for(const id of Object.keys(draft.featureChoices))if(id.startsWith('creation|'))delete draft.featureChoices[id];draft.allocations={};draft.abilityOptions={};draft.equipment={};draft.gearChoices={};if(key==='speciesId'){const sp=db.species.find(s=>builderId(s)===draft.speciesId);draft.subraceId=sp?.subraces?.[0]?.id??'';}}
 if(key==='subraceId'){for(const id of Object.keys(draft.featureChoices))if(id.startsWith('creation|species')||id.startsWith('creation|ancestry'))delete draft.featureChoices[id];draft.allocations=Object.fromEntries(Object.entries(draft.allocations).filter(([k])=>!k.startsWith('species:')));delete draft.abilityOptions['species'];}
 if(key.startsWith('abilityOptions.')){const optId=key.split('.')[1];draft.allocations=Object.fromEntries(Object.entries(draft.allocations).filter(([k])=>!k.startsWith(optId+':')));}}else if(input.dataset.score)draft.baseScores[input.dataset.score]=Number(input.value);
 else if(input.dataset.package){draft.equipment[input.dataset.package]=input.value;draft.gearChoices={};draft.armor='';draft.shield=false;}
 else if(input.dataset.buildChoice){const id=input.dataset.buildChoice,ctx=buildCharacter(draft,db),choice=ctx.choices.find(c=>c.id===id);let values=(draft.featureChoices[id]??[]).filter(value=>choice.options.some(option=>option.id===value));if(input.checked){if(choice.count===1)values=[input.value];else if(values.length>=choice.count){error='Choose at most '+choice.count+' options for '+choice.label+'.';input.checked=false;}else values=[...values,input.value];}else values=values.filter(v=>v!==input.value);draft.featureChoices[id]=values;}
 else if(input.dataset.note){draft.notes[input.dataset.note]=input.value;store();return;}else return;store();paint();
}
async function action(event){const tabBtn=event.target.closest('[data-spell-tab]');if(tabBtn){activeSpellTabs.set(tabBtn.dataset.spellChoiceId,Number(tabBtn.dataset.spellTab));paint();return;}const tagBtn=event.target.closest('[data-spell-tag]');if(tagBtn){const id=tagBtn.dataset.spellChoiceId,t=tagBtn.dataset.spellTag;if(!activeSpellFilters.has(id))activeSpellFilters.set(id,new Set());const f=activeSpellFilters.get(id);if(f.has(t))f.delete(t);else f.add(t);paint();return;}const clearBtn=event.target.closest('[data-spell-clear-filters]');if(clearBtn){const id=clearBtn.dataset.spellChoiceId||clearBtn.dataset.spellClearFilters;activeSpellFilters.delete(id);searches.delete(id);paint();return;}const button=event.target.closest('[data-builder-action],[data-builder-step]');if(!button||!root?.contains(button))return;event.preventDefault();error='';if(button.dataset.builderStep!=null){draft.step=Number(button.dataset.builderStep);markStepVisited(draft.step);store();paint();return;}switch(button.dataset.builderAction){case'close':store();onClose();return;case'reset':if(confirm('Discard this draft and start a new character?')){draft=newBuilderDraft();activeSpellTabs.clear();activeSpellFilters.clear();searches.clear();store();}break;case'back':draft.step=Math.max(0,draft.step-1);markStepVisited(draft.step);break;case'next':{const issues=builderProblems(draft,buildCharacter(draft,db)).filter(p=>p.step===draft.step);if(issues.length)error=issues.map(p=>p.message).join(' ');else{markStepVisited(draft.step);draft.step=Math.min(6,draft.step+1);markStepVisited(draft.step);}break;}case'create':{const ctx=buildCharacter(draft,db),problems=builderProblems(draft,ctx);if(problems.length){draft.step=problems[0].step;markStepVisited(draft.step);error=problems[0].message;break;}saving=true;paint();try{if(await onCreate(ctx.raw)===false)throw Error('The character could not be saved. Your draft is still available.');draft=newBuilderDraft();store();}catch(failure){error=failure.message;}finally{saving=false;}break;}}
 store();paint();}
export async function mountCharacterBuilder(container,{create,close}){try{draft=normalizeDraft(JSON.parse(localStorage.getItem(draftKey)));}catch{draft=newBuilderDraft();}root=container;onCreate=create;onClose=close;if(!root.dataset.builderBound){root.dataset.builderBound='true';root.addEventListener('click',action);root.addEventListener('toggle',event=>{const details=event.target;if(!details.matches?.('[data-choice-rules]')||!details.open||details.dataset.loaded)return;const option=buildCharacter(draft,db).choices.find(c=>c.id===details.dataset.choiceRules)?.options.find(o=>o.id===details.dataset.optionRules);if(option?.entries){details.insertAdjacentHTML('beforeend',formatEntries(option.entries));details.dataset.loaded='true';}},true);root.addEventListener('change',update);root.addEventListener('input',e=>{if(e.target.matches('[data-choice-search],[data-note],[data-build=name],[data-build=player]'))update(e);});}root.innerHTML='<p role="status">Loading character creation rules…</p>';try{db=await loadBuilderData();paint();}catch(failure){root.innerHTML=`<p role="alert">${escape(failure.message)}</p><button type="button" class="button outline" data-builder-action="close">Back to sheets</button>`;}}
